 12→import jlsm.table.internal.FieldIndex;
 13→import org.junit.jupiter.api.Test;
 14→
 15→class FieldIndexTest {
 16→
 17→    private MemorySegment stringKey(String key) {
 18→        byte[] bytes = key.getBytes(java.nio.charset.StandardCharsets.UTF_8);
 19→        MemorySegment seg = Arena.ofAuto().allocate(bytes.length);
 20→        seg.copyFrom(MemorySegment.ofArray(bytes));
 21→        return seg;
 22→    }
 23→
 24→    private List<MemorySegment> collect(Iterator<MemorySegment> it) {
 25→        var result = new ArrayList<MemorySegment>();
 26→        it.forEachRemaining(result::add);
 27→        return result;
 28→    }
 29→
 30→    @Test
 31→    void testEqualityLookup() throws IOException {
 32→        var def = new IndexDefinition("name", IndexType.EQUALITY);
 33→        var index = new FieldIndex(def);
 34→
 35→        index.onInsert(stringKey("pk1"), "Alice");
 36→        index.onInsert(stringKey("pk2"), "Bob");
 37→        index.onInsert(stringKey("pk3"), "Alice");
 38→
 39→        var results = collect(index.lookup(new Predicate.Eq("name", "Alice")));
 40→        assertEquals(2, results.size(), "Should find 2 entries with name=Alice");
 41→
 42→        var bobResults = collect(index.lookup(new Predicate.Eq("name", "Bob")));
 43→        assertEquals(1, bobResults.size(), "Should find 1 entry with name=Bob");
 44→
 45→        index.close();
 46→    }
 47→
 48→    @Test
 49→    void testRangeLookup() throws IOException {
 50→        var def = new IndexDefinition("age", IndexType.RANGE);
 51→        var index = new FieldIndex(def);
 52→
 53→        index.onInsert(stringKey("pk1"), 20);
 54→        index.onInsert(stringKey("pk2"), 30);
 55→        index.onInsert(stringKey("pk3"), 40);
 56→        index.onInsert(stringKey("pk4"), 50);
 57→
 58→        // Gt: age > 30 → should find 40, 50
 59→        var gtResults = collect(index.lookup(new Predicate.Gt("age", 30)));
 60→        assertEquals(2, gtResults.size(), "age > 30 should find 2 entries");
 61→
 62→        // Gte: age >= 30 → should find 30, 40, 50
 63→        var gteResults = collect(index.lookup(new Predicate.Gte("age", 30)));
 64→        assertEquals(3, gteResults.size(), "age >= 30 should find 3 entries");
 65→
 66→        // Lt: age < 30 → should find 20
 67→        var ltResults = collect(index.lookup(new Predicate.Lt("age", 30)));
 68→        assertEquals(1, ltResults.size(), "age < 30 should find 1 entry");
 69→
 70→        // Between: 25 <= age <= 45 → should find 30, 40
 71→        var betweenResults = collect(index.lookup(new Predicate.Between("age", 25, 45)));
 72→        assertEquals(2, betweenResults.size(), "25 <= age <= 45 should find 2 entries");
 73→
 74→        index.close();
 75→    }
 76→
 77→    @Test
 78→    void testUniqueConstraint() throws IOException {
 79→        var def = new IndexDefinition("email", IndexType.UNIQUE);
 80→        var index = new FieldIndex(def);
 81→
 82→        index.onInsert(stringKey("pk1"), "user@example.com");
 83→
 84→        assertThrows(DuplicateKeyException.class,
 85→                () -> index.onInsert(stringKey("pk2"), "user@example.com"),
 86→                "Should reject duplicate value in unique index");
 87→
 88→        index.close();
 89→    }
