 91→    @Test
 92→    void testDeleteRemovesEntry() throws IOException {
 93→        var def = new IndexDefinition("name", IndexType.EQUALITY);
 94→        var index = new FieldIndex(def);
 95→
 96→        index.onInsert(stringKey("pk1"), "Alice");
 97→        index.onInsert(stringKey("pk2"), "Alice");
 98→
 99→        index.onDelete(stringKey("pk1"), "Alice");
100→
101→        var results = collect(index.lookup(new Predicate.Eq("name", "Alice")));
102→        assertEquals(1, results.size(), "After delete, should find 1 entry");
103→
104→        index.close();
105→    }
106→
107→    @Test
108→    void testUpdateReplacesEntry() throws IOException {
109→        var def = new IndexDefinition("name", IndexType.RANGE);
110→        var index = new FieldIndex(def);
111→
112→        index.onInsert(stringKey("pk1"), "Alice");
113→        index.onUpdate(stringKey("pk1"), "Alice", "Carol");
114→
115→        var aliceResults = collect(index.lookup(new Predicate.Eq("name", "Alice")));
116→        assertEquals(0, aliceResults.size(), "Alice should be gone after update");
117→
118→        var carolResults = collect(index.lookup(new Predicate.Eq("name", "Carol")));
119→        assertEquals(1, carolResults.size(), "Carol should be present after update");
120→
121→        index.close();
122→    }
123→
124→    @Test
125→    void testSupportsCorrectPredicates() throws IOException {
